import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    G = int(input[idx])
    N = int(input[idx + 1])
    M = int(input[idx + 2])
    idx += 3

    mutation_table = {}
    for _ in range(N):
        a = int(input[idx])
        k = int(input[idx + 1])
        mutation_table[a] = [int(x) for x in input[idx + 2:idx + 2 + k]]
        idx += 2 + k

    antibodies = []
    for _ in range(M):
        l = int(input[idx])
        antibodies.append(tuple(int(x) for x in input[idx + 1:idx + 1 + l]))
        idx += 1 + l

    def bfs(start_gene):
        queue = deque([(start_gene, [])])
        visited = set()
        visited.add(start_gene)
        while queue:
            current_gene, current_sequence = queue.popleft()
            if current_gene in mutation_table:
                for next_gene in mutation_table[current_gene]:
                    new_sequence = current_sequence + [next_gene]
                    if next_gene not in visited:
                        visited.add(next_gene)
                        queue.append((next_gene, new_sequence))
                    else:
                        continue
                    if all(gene in [0, 1] for gene in new_sequence):
                        binary_string = tuple(new_sequence)
                        if not any(antibody in binary_string for antibody in antibodies):
                            return len(binary_string)
            else:
                if all(gene in [0, 1] for gene in current_sequence):
                    binary_string = tuple(current_sequence)
                    if not any(antibody in binary_string for antibody in antibodies):
                        return len(binary_string)
        return None

    results = []
    for start_gene in range(2, G):
        result = bfs(start_gene)
        if result is None:
            results.append("YES")
        else:
            results.append(f"NO {result}")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
